import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D8Tso2Ul.js";const p=JSON.parse('{"title":"Rol: Admin","description":"","frontmatter":{},"headers":[],"relativePath":"roles/admin.md","filePath":"roles/admin.md"}'),d={name:"roles/admin.md"};function i(s,e,n,l,c,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="rol-admin" tabindex="-1">Rol: Admin <a class="header-anchor" href="#rol-admin" aria-label="Permalink to &quot;Rol: Admin&quot;">​</a></h1><p>El <strong>administrador</strong> tiene la gestión completa de su tenant. Es el rol con mayor alcance dentro de una empresa cliente (no confundir con el superadmin del <code>tenant-0</code>, que tiene acceso cross-tenant).</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><ul><li>Configurar la empresa (datos, plan, personalización, módulos activos).</li><li>Crear y gestionar obras.</li><li>Gestionar personas y asignar roles.</li><li>Supervisar el cumplimiento documental de todas las obras.</li><li>Acceder a toda la reportería y KPIs del tenant.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Acceso</th></tr></thead><tbody><tr><td>Dashboard</td><td>✓ Completo (KPIs agregados de todas las obras)</td></tr><tr><td>Obras</td><td>✓ Crear, editar, avanzar fase</td></tr><tr><td>Documentos</td><td>✓ Completo</td></tr><tr><td>Firmas</td><td>✓ Completo</td></tr><tr><td>Incidentes</td><td>✓ Completo</td></tr><tr><td>Actividades</td><td>✓ Completo</td></tr><tr><td>Encuestas</td><td>✓ Completo</td></tr><tr><td>Asistente IA</td><td>✓ Completo</td></tr><tr><td>Personas</td><td>✓ Crear, editar, asignar roles</td></tr><tr><td>Bandeja de Entrada</td><td>✓ Completo</td></tr><tr><td>Tenants</td><td>✓ Configuración de la empresa</td></tr></tbody></table><h2 id="configuracion-exclusiva" tabindex="-1">Configuración exclusiva <a class="header-anchor" href="#configuracion-exclusiva" aria-label="Permalink to &quot;Configuración exclusiva&quot;">​</a></h2><p>El admin es el único rol que accede al módulo de <a href="/manual/modulos/tenants.html">Tenants</a>:</p><ul><li>Plan y límites (<code>maxWorkers</code>, <code>limiteObras</code>).</li><li>Módulos activos (<code>settings.modulosActivos</code>).</li><li>Reglas SST (<code>reglas.fasesObligatorias</code>, <code>requiereFirmaPin</code>).</li><li>Personalización UI (colores, logo, preferencias regionales).</li></ul><p>El admin se crea automáticamente durante el <a href="/manual/guia-inicio/onboarding.html">onboarding del tenant</a>.</p>',10)])])}const h=a(d,[["render",i]]);export{p as __pageData,h as default};
